function smoothPts(P, n = 10) { // Catmull-Rom
  const out = [];
  for (let i = 0; i < P.length - 1; i++) {
    const p0 = P[Math.max(0, i - 1)], p1 = P[i], p2 = P[i + 1], p3 = P[Math.min(P.length - 1, i + 2)];
    for (let k = 0; k < n; k++) {
      const t = k / n, t2 = t * t, t3 = t2 * t;
      out.push([0, 1].map(j => .5 * ((2 * p1[j]) + (-p0[j] + p2[j]) * t + (2 * p0[j] - 5 * p1[j] + 4 * p2[j] - p3[j]) * t2 + (-p0[j] + 3 * p1[j] - 3 * p2[j] + p3[j]) * t3)));
    }
  }
  out.push(P[P.length - 1]); return out;
}

function makeLeg(stops) {
  const pts = stops.map(s => { const ll = typeof s.p === 'string' ? PL[s.p] : s.p; return mp(ll[0], ll[1]); });
  const seg = [], mode = [];
  for (let i = 0; i < pts.length - 1; i++) {
    const P0 = pts[Math.max(0, i - 1)], P1 = pts[i], P2 = pts[i + 1], P3 = pts[Math.min(pts.length - 1, i + 2)];
    const n = 16;
    for (let k = 0; k < n; k++) {
      const t = k / n, t2 = t * t, t3 = t2 * t;
      seg.push([0, 1].map(j => .5 * ((2 * P1[j]) + (-P0[j] + P2[j]) * t + (2 * P0[j] - 5 * P1[j] + 4 * P2[j] - P3[j]) * t2 + (-P0[j] + 3 * P1[j] - 3 * P2[j] + P3[j]) * t3)));
      mode.push(stops[i + 1].sea ? 'sea' : stops[i + 1].arrest ? 'arrest' : 'land');
    }
  }
  seg.push(pts[pts.length - 1]); mode.push(mode[mode.length - 1]);
  const cum = [0]; for (let i = 1; i < seg.length; i++) cum.push(cum[i - 1] + Math.hypot(seg[i][0] - seg[i - 1][0], seg[i][1] - seg[i - 1][1]));
  const L = cum[cum.length - 1];
  const stopAt = stops.map((s, i) => cum[Math.min(i * 16, cum.length - 1)] / L);
  return { stops, pts, seg, mode, cum, L, stopAt };
}
function legAt(leg, p) {
  const d = clamp(p) * leg.L; let i = 1; while (i < leg.cum.length - 1 && leg.cum[i] < d) i++;
  const a = leg.cum[i - 1], b = leg.cum[i], k = b > a ? (d - a) / (b - a) : 0;
  const A = leg.seg[i - 1], B = leg.seg[i];
  return { x: lerp(A[0], B[0], k), y: lerp(A[1], B[1], k), i, dx: B[0] - A[0], mode: leg.mode[i] };
}

function drawRoute(g, leg, p, T, style) {
  const n = Math.floor(clamp(p) * (leg.seg.length - 1));
  if (p <= 0) return;
  const hp = legAt(leg, p);
  g.save(); g.lineCap = 'round'; g.lineJoin = 'round';
  let cur = null;
  const flush = () => { if (cur) g.stroke(); };
  for (let i = 1; i <= n + 1; i++) {
    const m = leg.mode[i] || 'land';
    const [x0, y0] = T(leg.seg[i - 1]); const [x1, y1] = i <= n ? T(leg.seg[i]) : T([hp.x, hp.y]);
    if (m !== cur) {
      flush(); cur = m; g.beginPath();
      if (style === 'ghost') { g.strokeStyle = 'rgba(168,50,43,.28)'; g.lineWidth = 2; g.setLineDash([6, 6]); }
      else if (m === 'arrest') { g.strokeStyle = 'rgba(96,20,16,.95)'; g.lineWidth = 4; g.setLineDash([3, 7]); }
      else if (m === 'sea') { g.strokeStyle = 'rgba(168,50,43,.85)'; g.lineWidth = 3; g.setLineDash([2, 9]); }
      else { g.strokeStyle = 'rgba(168,50,43,.9)'; g.lineWidth = 3.4; g.setLineDash([14, 7]); }
      g.moveTo(x0, y0);
    }
    g.lineTo(x1, y1);
  }
  flush(); g.restore();
  return hp;
}
